/// Construct the copy helper for the bounded multi-endpoint row layout.
pub fn build_copy_logup_helper(rows: &[CopyLogUpRow], chi: QM31) -> Result<Vec<QM31>, LogUpError> {
    let mut helper = Vec::with_capacity(rows.len());
    for (row_index, row) in rows.iter().enumerate() {
        let mut value = QM31::ZERO;
        for (producer_value, weight) in row.producer_values.into_iter().zip(row.producer_weights) {
            if weight != M31::ZERO {
                value = value.add(
                    chi.sub(producer_value)
                        .try_inv()
                        .ok_or(LogUpError::ActivePole {
                            row: row_index,
                            side: LogUpSide::Producer,
                        })?
                        .mul_m31(weight),
                );
            }
        }
        for (consumer_value, weight) in row.consumer_values.into_iter().zip(row.consumer_weights) {
            if weight != M31::ZERO {
                value = value.sub(
                    chi.sub(consumer_value)
                        .try_inv()
                        .ok_or(LogUpError::ActivePole {
                            row: row_index,
                            side: LogUpSide::Consumer,
                        })?
                        .mul_m31(weight),
                );
            }
        }
        helper.push(value);
    }
    Ok(helper)
}

/// Construct the unique forest LogUp helper from the literal typed copy
/// registry.  The append index remains an explicit input because append-side
/// links are selected by its live lane-path bits.
pub fn build_pool_v1_pair_forest_copy_helper_v1(
    trace: &PoolV1PairForestTraceV1,
    append_index: u64,
    lambda: QM31,
    chi: QM31,
) -> Result<Vec<QM31>, PoolV1PairTraceErrorV1> {
    let rows = pool_v1_pair_forest_copy_rows_v1(trace, append_index, lambda)?;
    build_copy_logup_helper(&rows, chi).map_err(|_| PoolV1PairTraceErrorV1::CopyImbalance)
}
